# ----------------------------------------------------------------- market-intelligence helpers (added)
TD = 252
SECTOR = {s: ("IT" if s in ("TCS", "Infosys") else "Auto") for s in STOCKS}


def perf_metrics(p, rf=0.06):
    """Return / risk statistics for one price series (annualised with 252 trading days)."""
    r = p.pct_change().dropna()
    yrs = max((p.index[-1] - p.index[0]).days / 365.25, 1e-9)
    tot = p.iloc[-1] / p.iloc[0] - 1
    cagr = (1 + tot) ** (1 / yrs) - 1
    vol = r.std() * np.sqrt(TD)
    dvol = r[r < 0].std() * np.sqrt(TD)
    mdd = (p / p.cummax() - 1).min()
    var95 = np.percentile(r, 5)
    mret = p.groupby([p.index.year, p.index.month]).last().pct_change().dropna()
    return dict(total=tot, cagr=cagr, vol=vol, mdd=mdd, sharpe=(cagr - rf) / vol, sortino=(cagr - rf) / dvol,
                calmar=cagr / abs(mdd), var95=var95, cvar95=r[r <= var95].mean(),
                best_m=mret.max(), worst_m=mret.min())


def ind(p):
    """Technical indicators. Data is close-only, so ATR is a proxy (14-day mean absolute close-to-close move)."""
    d = pd.DataFrame({"close": p})
    for n in (20, 50, 200):
        d[f"sma{n}"] = p.rolling(n).mean()
    for n in (20, 50):
        d[f"ema{n}"] = p.ewm(span=n, adjust=False).mean()
    sd = p.rolling(20).std()
    d["bb_up"], d["bb_lo"] = d.sma20 + 2 * sd, d.sma20 - 2 * sd
    dl = p.diff()
    g = dl.clip(lower=0).ewm(alpha=1 / 14, adjust=False).mean()
    l = (-dl.clip(upper=0)).ewm(alpha=1 / 14, adjust=False).mean()
    d["rsi"] = 100 - 100 / (1 + g / l)
    d["macd"] = p.ewm(span=12, adjust=False).mean() - p.ewm(span=26, adjust=False).mean()
    d["macd_sig"] = d.macd.ewm(span=9, adjust=False).mean()
    d["atr"] = dl.abs().rolling(14).mean()
    d["roc"] = p.pct_change(10) * 100
    d["rvol"] = p.pct_change().rolling(20).std() * np.sqrt(TD) * 100
    return d


def mm(s):
    rng = s.max() - s.min()
    return (s - s.min()) / rng * 100 if rng > 0 else s * 0 + 50


def scorecard(px, rf=0.06):
    """0-100 analytical indicators (relative across the stocks shown). Not investment recommendations."""
    rows = {}
    for s in px.columns:
        p = px[s].dropna()
        m, d = perf_metrics(p, rf), ind(p)
        rows[s] = dict(mom=p.iloc[-1] / p.iloc[-127] - 1, trend=(d.close > d.sma50).tail(120).mean() * 100,
                       vol=m["vol"], risk=-m["cvar95"], dd=-m["mdd"], sig=d.sma20.iloc[-1] / d.sma50.iloc[-1] - 1)
    r = pd.DataFrame(rows).T
    sc = pd.DataFrame({"Momentum": mm(r.mom), "Trend strength": r.trend, "Volatility": mm(r.vol),
                       "Risk (tail loss)": mm(r.risk), "Drawdown": mm(r.dd), "Signal strength": mm(r.sig)})
    raw = df_wide("raw")[list(px.columns)]
    sc["Data quality"] = (100 - 40 * (raw.pct_change().abs() > .25).sum() - 100 * raw.isna().mean()).clip(0, 100)
    return sc.round(0)


def min_var(cov):
    """Long-only minimum-variance weights (active-set heuristic: drop the most negative weight and re-solve)."""
    n, idx = len(cov), list(range(len(cov)))
    while True:
        w = np.linalg.solve(cov[np.ix_(idx, idx)], np.ones(len(idx)))
        w = w / w.sum()
        if (w >= 0).all() or len(idx) == 1:
            break
        idx.pop(int(np.argmin(w)))
    out = np.zeros(n)
    out[idx] = w if len(idx) > 1 else 1.0
    return out


def build_insights(px, rf, trend):
    """Rule-based narrative generated from the data: returns (summary, [(category, headline, detail)])."""
    mt = pd.DataFrame({s: perf_metrics(px[s].dropna(), rf) for s in px}).T.astype(float)
    ret = px.pct_change().dropna()
    corr = ret.corr()
    iu = np.triu_indices(len(corr), 1)
    pairs = pd.Series(corr.values[iu], index=[f"{corr.index[i]} / {corr.columns[j]}" for i, j in zip(*iu)]).sort_values()
    avg_corr = float(corr.values[iu].mean())
    rv = ret.tail(60).std() / ret.std()
    rsi = {s: ind(px[s].dropna()).rsi.iloc[-1] for s in px}
    best, worst, hv = mt.cagr.idxmax(), mt.cagr.idxmin(), mt.vol.idxmax()
    ddw, sh = mt.mdd.idxmin(), mt.sharpe.idxmax()
    buys = trend[trend.signal == "Buy"].stock.tolist()
    hot, cold = [s for s, v in rsi.items() if v > 70], [s for s, v in rsi.items() if v < 30]
    same = [corr.iloc[i, j] for i, j in zip(*iu) if SECTOR[corr.index[i]] == SECTOR[corr.columns[j]]]
    diff = [corr.iloc[i, j] for i, j in zip(*iu) if SECTOR[corr.index[i]] != SECTOR[corr.columns[j]]]
    jumps = (df_wide("raw").pct_change().abs() > .25).sum()
    flagged = jumps[jumps > 0].index.tolist()
    cons = (mt.vol.rank() + mt.mdd.abs().rank()).idxmin()
    top_rv, low_rv = rv.idxmax(), rv.idxmin()
    cards = [
        ("Performance", f"{best} led the period",
         f"{best}: {mt.total[best]*100:+.1f}% total, {mt.cagr[best]*100:+.1f}% CAGR. {worst} trailed at {mt.total[worst]*100:+.1f}% total."),
        ("Risk", f"{hv} carried the most volatility",
         f"{hv}: {mt.vol[hv]*100:.1f}% annualised volatility. Deepest drawdown: {ddw} ({mt.mdd[ddw]*100:.1f}%). "
         f"Best Sharpe (rf {rf*100:.1f}%): {sh} ({mt.sharpe[sh]:.2f})."),
        ("Volatility change", f"{top_rv} is the most unsettled right now",
         f"Last-60-day volatility is {rv[top_rv]:.2f}x its full-period level for {top_rv}, and {rv[low_rv]:.2f}x for {low_rv} (calmest)."),
        ("Trend", f"{len(buys)} of {len(trend)} stocks sit on a golden-cross Buy",
         f"Buy: {', '.join(buys) or 'none'}. RSI above 70: {', '.join(hot) or 'none'}. RSI below 30: {', '.join(cold) or 'none'}."),
        ("Diversification", f"Average pairwise correlation is {avg_corr:.2f}",
         f"Closest pair: {pairs.index[-1]} ({pairs.iloc[-1]:.2f}). Most diversifying: {pairs.index[0]} ({pairs.iloc[0]:.2f})."
         + (f" Same-sector pairs average {np.mean(same):.2f} vs {np.mean(diff):.2f} across sectors, "
            f"{'consistent with' if np.mean(same) > np.mean(diff) else 'not consistent with'} sector-level behaviour in this sample." if same and diff else "")),
        ("Data quality", "Bonus issues detected in the raw feed" if flagged else "No large one-day gaps in the raw feed",
         (f"{', '.join(flagged)} show >25% one-day price gaps in raw prices. Everything here uses bonus-adjusted prices, so returns and signals are not distorted."
          if flagged else "No >25% single-day price gaps found.")),
        ("Business", "Different objectives point to different names",
         f"Capital preservation lens: {cons} (lowest combined volatility and drawdown rank). Growth lens: {best}. "
         f"Risk-adjusted lens: {sh}. Historical sample only, not a forecast."),
    ]
    summary = (f"{best} led on growth ({mt.cagr[best]*100:+.1f}% CAGR) while {hv} was the most volatile; "
               f"{len(buys)} of {len(trend)} stocks show a Buy signal and average correlation is {avg_corr:.2f}.")
    return summary, cards


# ----------------------------------------------------------------- PDF insights report (needs: pip install reportlab matplotlib)
def make_insights_pdf(px, rf, summary, cards, sc, colors):
    """Build a multi-page PDF insights report from the dashboard's own numbers (bonus-adjusted prices)."""
    import io
    from datetime import date
    from xml.sax.saxutils import escape
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    from reportlab.lib import colors as rl
    from reportlab.lib.pagesizes import A4
    from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
    from reportlab.lib.units import mm as MM
    from reportlab.platypus import (SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, Image, PageBreak, KeepTogether)

    def clean(t):
        t = str(t)
        for a, b in (("\u2212", "-"), ("\u2013", "-"), ("\u2014", "-"), ("\u2192", "->"), ("\u2018", "'"), ("\u2019", "'"),
                     ("\u201c", '"'), ("\u201d", '"')):
            t = t.replace(a, b)
        return escape(t.encode("latin-1", "replace").decode("latin-1"))

    stocks = list(px.columns)
    M = pd.DataFrame({s: perf_metrics(px[s].dropna(), rf) for s in stocks}).T.astype(float)
    ret = px.pct_change().dropna()
    corr = ret.corr()
    start, end = px.index[0], px.index[-1]

    ss = getSampleStyleSheet()
    NAVY, BLUE, GREY = rl.HexColor("#0b2545"), rl.HexColor("#1d70b8"), rl.HexColor("#5b6b7f")
    H1 = ParagraphStyle("H1", parent=ss["Heading1"], textColor=NAVY, fontSize=17, spaceBefore=6, spaceAfter=8)
    H2 = ParagraphStyle("H2", parent=ss["Heading2"], textColor=BLUE, fontSize=12, spaceBefore=8, spaceAfter=4)
    BODY = ParagraphStyle("B", parent=ss["BodyText"], fontSize=9.5, leading=13.5)
    SMALL = ParagraphStyle("S", parent=BODY, fontSize=8, leading=10.5, textColor=GREY)
    KICK = ParagraphStyle("K", parent=BODY, fontSize=7.5, textColor=BLUE, leading=9, fontName="Helvetica-Bold")
    HEAD = ParagraphStyle("Hd", parent=BODY, fontSize=10.5, leading=13, fontName="Helvetica-Bold", textColor=NAVY)

    def fig_img(fig, w_mm, h_mm):
        buf = io.BytesIO()
        fig.savefig(buf, format="png", dpi=170, bbox_inches="tight", facecolor="white")
        plt.close(fig)
        buf.seek(0)
        return Image(buf, width=w_mm * MM, height=h_mm * MM)

    def table(df, col_w=None, first_w=None):
        data = [[""] + list(df.columns)] + [[i] + list(r) for i, r in zip(df.index, df.values.tolist())]
        t = Table(data, colWidths=col_w, repeatRows=1)
        t.setStyle(TableStyle([
            ("BACKGROUND", (0, 0), (-1, 0), NAVY), ("TEXTCOLOR", (0, 0), (-1, 0), rl.white),
            ("FONTNAME", (0, 0), (-1, 0), "Helvetica-Bold"), ("FONTSIZE", (0, 0), (-1, -1), 8),
            ("FONTNAME", (0, 1), (0, -1), "Helvetica-Bold"),
            ("ALIGN", (1, 0), (-1, -1), "RIGHT"), ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
            ("ROWBACKGROUNDS", (0, 1), (-1, -1), [rl.white, rl.HexColor("#eef3f9")]),
            ("GRID", (0, 0), (-1, -1), 0.25, rl.HexColor("#c8d3e0")),
            ("TOPPADDING", (0, 0), (-1, -1), 4), ("BOTTOMPADDING", (0, 0), (-1, -1), 4)]))
        return t

    story = []
    # ---- page 1: title + summary + insight cards
    story += [Paragraph("Stock Market Analysis in SQL", ParagraphStyle("T", parent=H1, fontSize=24, spaceAfter=2)),
              Paragraph("Market Insights Report", ParagraphStyle("T2", parent=H2, fontSize=14, spaceBefore=0)),
              Paragraph(clean(f"{len(stocks)} NSE stocks | {start:%d %b %Y} to {end:%d %b %Y} | {len(px)} trading days | "
                              f"bonus-adjusted prices | risk-free rate {rf*100:.1f}% | generated {date.today():%d %b %Y}"), SMALL),
              Spacer(1, 10), Paragraph("Executive summary", H2)]
    box = Table([[Paragraph(clean(summary), ParagraphStyle("Sm", parent=BODY, fontSize=10.5, leading=15, textColor=NAVY))]],
                colWidths=[178 * MM])
    box.setStyle(TableStyle([("BACKGROUND", (0, 0), (-1, -1), rl.HexColor("#e8f1fb")), ("BOX", (0, 0), (-1, -1), 0.8, BLUE),
                             ("LEFTPADDING", (0, 0), (-1, -1), 10), ("RIGHTPADDING", (0, 0), (-1, -1), 10),
                             ("TOPPADDING", (0, 0), (-1, -1), 9), ("BOTTOMPADDING", (0, 0), (-1, -1), 9)]))
    story += [box, Spacer(1, 8), Paragraph("Key insights", H2)]
    for cat, head, det in cards:
        c = Table([[Paragraph(clean(cat).upper(), KICK)], [Paragraph(clean(head), HEAD)], [Paragraph(clean(det), BODY)]],
                  colWidths=[178 * MM])
        c.setStyle(TableStyle([("BOX", (0, 0), (-1, -1), 0.5, rl.HexColor("#c8d3e0")), ("LINEBEFORE", (0, 0), (0, -1), 3, BLUE),
                               ("LEFTPADDING", (0, 0), (-1, -1), 9), ("TOPPADDING", (0, 0), (-1, -1), 2),
                               ("BOTTOMPADDING", (0, 0), (-1, -1), 2)]))
        story += [KeepTogether([c]), Spacer(1, 5)]

    # ---- page 2: performance charts
    story += [PageBreak(), Paragraph("Performance and risk", H1)]
    fig, ax = plt.subplots(figsize=(8.2, 3.6))
    reb = px / px.iloc[0] * 100
    for s in stocks:
        ax.plot(reb.index, reb[s], label=s, color=colors.get(s), lw=1.4)
    ax.set_title("Growth of 100 invested at the start (bonus-adjusted)", fontsize=10, loc="left")
    ax.grid(alpha=.25); ax.legend(ncol=len(stocks), fontsize=7, frameon=False, loc="upper left")
    for sp in ("top", "right"): ax.spines[sp].set_visible(False)
    story += [fig_img(fig, 178, 78), Spacer(1, 6)]

    fig, (a1, a2) = plt.subplots(1, 2, figsize=(8.2, 3.5))
    for s in stocks:
        a1.scatter(M.vol[s] * 100, M.cagr[s] * 100, s=abs(M.mdd[s]) * 900, color=colors.get(s), alpha=.75)
        a1.annotate(s, (M.vol[s] * 100, M.cagr[s] * 100), fontsize=7, ha="center", va="bottom", xytext=(0, 7), textcoords="offset points")
    a1.set_xlabel("Annualised volatility %", fontsize=8); a1.set_ylabel("CAGR %", fontsize=8)
    a1.set_title("Risk vs return (bubble = max drawdown)", fontsize=9, loc="left"); a1.grid(alpha=.25); a1.margins(x=.15, y=.18)
    im = a2.imshow(corr.values, cmap="RdBu_r", vmin=-1, vmax=1)
    a2.set_xticks(range(len(stocks))); a2.set_xticklabels(stocks, rotation=45, ha="right", fontsize=7)
    a2.set_yticks(range(len(stocks))); a2.set_yticklabels(stocks, fontsize=7)
    for i in range(len(stocks)):
        for j in range(len(stocks)):
            a2.text(j, i, f"{corr.values[i, j]:.2f}", ha="center", va="center", fontsize=6.5, color="white" if abs(corr.values[i, j]) > .6 else "black")
    a2.set_title("Daily-return correlation", fontsize=9, loc="left")
    fig.tight_layout()
    story += [fig_img(fig, 178, 76), Spacer(1, 6), Paragraph("Risk and return metrics", H2)]

    mt = pd.DataFrame({"Total return": M.total * 100, "CAGR": M.cagr * 100, "Volatility": M.vol * 100, "Max drawdown": M.mdd * 100,
                       "Sharpe": M.sharpe, "Sortino": M.sortino, "Calmar": M.calmar,
                       "VaR 95% (d)": M.var95 * 100, "CVaR 95% (d)": M.cvar95 * 100}).round(2)
    mt = mt.astype(object)
    for c in mt.columns:
        mt[c] = [f"{v:.2f}" for v in mt[c]] if c in ("Sharpe", "Sortino", "Calmar") else [f"{v:+.1f}%" for v in mt[c]]
    story += [table(mt), Spacer(1, 3),
              Paragraph("Percentages are period or annualised figures on bonus-adjusted prices; VaR and CVaR are historical daily values. "
                        "Sharpe and Sortino use the risk-free rate shown on page 1.", SMALL)]

    # ---- page 3: scorecard + notes
    story += [PageBreak(), Paragraph("Stock scorecard", H1),
              Paragraph("0-100 analytical indicators, relative across these stocks. For Volatility, Risk and Drawdown a higher score means "
                        "more of it. Indicators only, not recommendations.", BODY), Spacer(1, 6)]
    story += [table(sc.astype(int).astype(str)), Spacer(1, 10)]

    story += [Paragraph("Data quality", H2),
              Paragraph("Raw exchange prices contain one-day gaps of around 50% for TCS (31 May 2018) and Infosys (15 Jun 2015). These are "
                        "1:1 bonus issues, not crashes. All figures in this report use bonus-adjusted prices so returns, risk and signals "
                        "are not distorted.", BODY),
              Paragraph("Method notes", H2),
              Paragraph("Volatility, CAGR and ratios are annualised on 252 trading days. Signals use the 20/50-day golden-cross rule. "
                        "The dataset is close-only, so ATR is a proxy and intraday behaviour is not captured.", BODY),
              Paragraph("Limitations and disclaimer", H2),
              Paragraph("The sample is small (a handful of stocks over about 3.5 years) and entirely historical. Backtests ignore "
                        "transaction costs, taxes and slippage. This report is educational analysis and not investment advice.", BODY)]

    def footer(canvas, doc):
        canvas.saveState(); canvas.setFont("Helvetica", 7.5); canvas.setFillColor(GREY)
        canvas.drawString(16 * MM, 10 * MM, "Stock Market Analysis in SQL - Insights report")
        canvas.drawRightString(A4[0] - 16 * MM, 10 * MM, f"Page {doc.page}")
        canvas.restoreState()

    out = io.BytesIO()
    SimpleDocTemplate(out, pagesize=A4, leftMargin=16 * MM, rightMargin=16 * MM, topMargin=15 * MM, bottomMargin=18 * MM,
                      title="Stock Market Analysis Insights", author="Stock Market Analysis in SQL").build(story, onFirstPage=footer, onLaterPages=footer)
    return out.getvalue()


