    fig.add_vline(x=evd, line_dash="dash", line_color="#666")
    fig.update_layout(height=380, title=f"{ev}: 1:1 bonus issue, first day at new price {evd:%d %b %Y}", yaxis_title="Rs", hovermode="x unified")
    st.plotly_chart(futuristic_fig(fig), width="stretch")
    st.markdown("A 1:1 bonus doubles the number of shares, so the price halves. Shareholders lose nothing. "
                "Unadjusted data corrupts **returns, moving averages and signals** around the date.")

    r_raw = ((df_wide("raw").iloc[-1] / df_wide("raw").iloc[0] - 1) * 100).rename("Raw %")
    r_adj = ((df_wide("adjusted").iloc[-1] / df_wide("adjusted").iloc[0] - 1) * 100).rename("Adjusted %")
    cmp = pd.concat([r_raw, r_adj], axis=1).reset_index().melt("stock", var_name="basis", value_name="pct")
    fig = px.bar(cmp, x="stock", y="pct", color="basis", barmode="group", text="pct",
                 color_discrete_map={"Raw %": "#bbbbbb", "Adjusted %": "#1f77b4"}, title="Total return: raw vs adjusted")
    fig.update_traces(texttemplate="%{text:.1f}%", textposition="outside")
    fig.update_layout(height=400, xaxis_title="", yaxis_title="% change", legend_title="")
    st.plotly_chart(futuristic_fig(fig), width="stretch")

    s_raw, s_adj = df_signals("raw"), df_signals("adjusted")
    cnt = lambda x, n: x.groupby("stock").signal.agg(buys=lambda v: (v == "Buy").sum(), sells=lambda v: (v == "Sell").sum()).add_suffix(n)
    tr = pd.concat([cnt(s_raw, "_raw"), cnt(s_adj, "_adj")], axis=1)
    tr["trend_raw"] = A.current_trend(CON, "raw").set_index("stock").trend
    tr["trend_adj"] = A.current_trend(CON, "adjusted").set_index("stock").trend
    st.markdown("**Effect on signals**")
