# ================================================================= TECHNICAL ANALYSIS
with tab_ta:
    c1, c2 = st.columns([1, 2])
    ta_s = c1.selectbox("Stock", STOCKS, key="ta_stock")
    D = ind(PXA[ta_s].dropna())
    ta_rng = c2.slider("Date range", D.index.min().date(), D.index.max().date(),
                       (D.index.min().date(), D.index.max().date()), key="ta_rng")
    ov = st.multiselect("Overlays", ["SMA 20", "SMA 50", "SMA 200", "EMA 20", "EMA 50", "Bollinger Bands"],
                        default=["SMA 20", "SMA 50", "Bollinger Bands"], key="ta_ov")
    L = D.iloc[-1]
    trend_lbl = "🟢 Positive" if (L.close > L.sma50 and L.sma20 > L.sma50) else "🔴 Negative" if (L.close < L.sma50 and L.sma20 < L.sma50) else "🟡 Mixed"
    mom_lbl = "🟢 Strong" if L.rsi >= 60 else "🔴 Weak" if L.rsi <= 40 else "🟡 Neutral"
    vr = L.rvol / D.rvol.median()
    vol_lbl = "🔴 Elevated" if vr > 1.25 else "🟢 Calm" if vr < 0.8 else "🟡 Moderate"
    k = st.columns(5)
    k[0].metric("Trend", trend_lbl)
    k[1].metric("Momentum", mom_lbl)
    k[2].metric("Volatility", vol_lbl)
    k[3].metric("RSI (14)", f"{L.rsi:.1f}")
    k[4].metric("MACD", "Positive" if L.macd > L.macd_sig else "Negative")
    Dv = D.loc[pd.Timestamp(ta_rng[0]):pd.Timestamp(ta_rng[1])]
    fig = make_subplots(rows=3, cols=1, shared_xaxes=True, row_heights=[.6, .2, .2], vertical_spacing=.03)
    fig.add_scatter(x=Dv.index, y=Dv.close, name="Close", line=dict(color="#e9fbff", width=1.5), row=1, col=1)
    if "Bollinger Bands" in ov:
        bb = dict(color="rgba(0,229,255,.35)", width=1)
        fig.add_scatter(x=Dv.index, y=Dv.bb_lo, name="BB lower", line=bb, row=1, col=1)
        fig.add_scatter(x=Dv.index, y=Dv.bb_up, name="BB upper", line=bb, fill="tonexty", fillcolor="rgba(0,229,255,.07)", row=1, col=1)
    ov_col = {"sma20": "#1f77b4", "sma50": "#ff7f0e", "sma200": "#c084fc", "ema20": "#39ff9a", "ema50": "#ffd166"}
    for o in ov:
        key = o.lower().replace(" ", "")
        if key in ov_col:
            fig.add_scatter(x=Dv.index, y=Dv[key], name=o, line=dict(color=ov_col[key], width=1.8), row=1, col=1)
    fig.add_scatter(x=Dv.index, y=Dv.rsi, name="RSI", line=dict(color="#67f7ff"), row=2, col=1)
    fig.add_hline(y=70, line_dash="dot", line_color="#d62728", row=2, col=1)
    fig.add_hline(y=30, line_dash="dot", line_color="#0a8f3c", row=2, col=1)
    fig.add_bar(x=Dv.index, y=Dv.macd - Dv.macd_sig, name="MACD hist", marker_color="rgba(139,223,242,.45)", row=3, col=1)
    fig.add_scatter(x=Dv.index, y=Dv.macd, name="MACD", line=dict(color="#ff7f0e"), row=3, col=1)
    fig.add_scatter(x=Dv.index, y=Dv.macd_sig, name="Signal", line=dict(color="#39ff9a"), row=3, col=1)
    fig.update_layout(height=780, hovermode="x unified", legend=dict(orientation="h", y=1.06), title=f"{ta_s}: price, RSI and MACD")
