# ================================================================= PORTFOLIO LAB
with tab_port:
    sel = st.multiselect("Stocks in the portfolio", STOCKS, default=STOCKS, key="pf_sel")
    mode = st.radio("Weighting", ["Equal weight", "Custom weight", "Minimum volatility", "Risk balanced (inverse vol)"],
                    horizontal=True, key="pf_mode")
    if len(sel) < 2:
        st.info("Pick at least two stocks.")
    else:
        P = PXA[sel].dropna()
        R = P.pct_change().dropna()
        cov, mu, n = R.cov().values * TD, R.mean().values * TD, len(sel)
        if mode == "Custom weight":
            cw = st.columns(n)
            wr = np.array([c.number_input(s, 0.0, 100.0, round(100 / n, 1), key=f"pf_w_{s}") for c, s in zip(cw, sel)])
            w = wr / wr.sum() if wr.sum() > 0 else np.ones(n) / n
        elif mode == "Minimum volatility":
            w = min_var(cov)
        elif mode.startswith("Risk"):
            iv = 1 / np.sqrt(np.diag(cov))
            w = iv / iv.sum()
        else:
            w = np.ones(n) / n
        eq = pd.Series(100 * np.r_[1, np.cumprod(1 + R.values @ w)], index=P.index)
        eq_ew = pd.Series(100 * np.r_[1, np.cumprod(1 + R.values.mean(axis=1))], index=P.index)
        pm = perf_metrics(eq, RF)
        divr = float(w @ np.sqrt(np.diag(cov)) / np.sqrt(w @ cov @ w))
        k = st.columns(5)
        k[0].metric("Portfolio return", fmt_pct(pm["total"] * 100))
        k[1].metric("Volatility", f"{pm['vol']*100:.1f}%")
        k[2].metric("Max drawdown", f"{pm['mdd']*100:.1f}%")
        k[3].metric("Sharpe ratio", f"{pm['sharpe']:.2f}")
        k[4].metric("Diversification ratio", f"{divr:.2f}x", help="Weighted-average stock volatility divided by portfolio volatility. Above 1 means diversification is helping.")
        c1, c2 = st.columns(2)
        fig = px.pie(names=sel, values=w * 100, hole=.55, color=sel, color_discrete_map=COLORS, title="Allocation")
        c1.plotly_chart(futuristic_fig(fig), width="stretch")
        fig = px.imshow(R.corr().round(2), text_auto=True, color_continuous_scale="RdBu_r", zmin=-1, zmax=1, title="Correlation of daily returns")
        c2.plotly_chart(futuristic_fig(fig), width="stretch")
        fig = go.Figure()
        fig.add_scatter(x=eq.index, y=eq, name="Selected portfolio", line=dict(color="#39ff9a", width=2.2))
        fig.add_scatter(x=eq_ew.index, y=eq_ew, name="Equal weight", line=dict(color="#9aa0a6", width=1.4, dash="dot"))
        fig.update_layout(height=380, title="Portfolio equity curve (growth of 100, daily-rebalanced)", hovermode="x unified", legend=dict(orientation="h", y=1.1))
        st.plotly_chart(futuristic_fig(fig), width="stretch")
        c3, c4 = st.columns(2)
        dd = (eq / eq.cummax() - 1) * 100
        fig = go.Figure(go.Scatter(x=dd.index, y=dd, fill="tozeroy", line=dict(color="#d62728"), name="Drawdown %"))
        fig.update_layout(height=360, title="Drawdown %")
        c3.plotly_chart(futuristic_fig(fig), width="stretch")
        Wr = np.random.default_rng(7).dirichlet(np.ones(n), 3000)
        pr, pv = Wr @ mu, np.sqrt(np.einsum("ij,jk,ik->i", Wr, cov, Wr))
        wmv = min_var(cov)
        fig = go.Figure(go.Scatter(x=pv * 100, y=pr * 100, mode="markers", name="Random portfolios",
                                   marker=dict(size=4, color=(pr - RF) / pv, colorscale="Viridis", showscale=True, colorbar=dict(title="Sharpe"))))
        fig.add_scatter(x=[pm["vol"] * 100], y=[float(w @ mu) * 100], mode="markers", name="Selected",
                        marker=dict(symbol="star", size=16, color="#ff7f0e", line=dict(width=1, color="white")))
        fig.add_scatter(x=[float(np.sqrt(wmv @ cov @ wmv)) * 100], y=[float(wmv @ mu) * 100], mode="markers", name="Min volatility",
                        marker=dict(symbol="diamond", size=13, color="#67f7ff", line=dict(width=1, color="white")))
        fig.update_layout(height=360, title="Risk / return map (3,000 random long-only mixes)", xaxis_title="Volatility %", yaxis_title="Arithmetic return %", legend=dict(orientation="h", y=1.12))
        c4.plotly_chart(futuristic_fig(fig), width="stretch")
        st.caption("In-sample, long-only, no costs or taxes. The efficient-frontier cloud is a random-mix approximation. Minimum-volatility weights use a simple active-set solver.")

# ================================================================= SCENARIO LAB
with tab_scn:
    c1, c2, c3, c4 = st.columns([1, 1.2, 1.2, 1.6])
    sc_s = c1.selectbox("Stock", STOCKS, key="scn_stock")
    amt = c2.number_input("Investment amount (₹)", 1000, 100000000, 100000, 10000, key="scn_amt")
    yrs = c3.slider("Holding period (years)", 1, 3, 3, key="scn_yrs")
    scen = c4.radio("Scenario", ["Historical", "Bull", "Base", "Bear"], horizontal=True, key="scn_kind")
    p = PXA[sc_s].dropna()
    rr, h = p.pct_change().dropna().values, yrs * TD
    paths = np.cumprod(1 + rr[np.random.default_rng(42).integers(0, len(rr), (600, h))], axis=1)
    if scen == "Historical":
        roll = (p.shift(-h) / p - 1).dropna()
        if len(roll):
            i0 = (roll - roll.median()).abs().idxmin()
            seg = p.loc[i0:].iloc[:h + 1]
            end_val, dd_sel = amt * (1 + roll[i0]), (seg / seg.cummax() - 1).min()
            note = (f"Median of {len(roll)} actual {yrs}-year windows (worst {roll.min()*100:+.0f}%, best {roll.max()*100:+.0f}%).")
        else:
            end_val, dd_sel, note = amt, 0.0, "Not enough history for this holding period."
    else:
        target = np.percentile(paths[:, -1], {"Bull": 90, "Base": 50, "Bear": 10}[scen])
        pth = np.r_[1, paths[np.abs(paths[:, -1] - target).argmin()]]
        end_val, dd_sel = amt * pth[-1], (pth / np.maximum.accumulate(pth) - 1).min()
        note = f"{scen} = the {({'Bull': '90th', 'Base': '50th', 'Bear': '10th'})[scen]} percentile of 600 bootstrapped paths built from {sc_s}'s own daily returns."
    k = st.columns(4)
    k[0].metric("Initial capital", f"₹{amt:,.0f}")
    k[1].metric("Ending value", f"₹{end_val:,.0f}")
    k[2].metric("Growth", fmt_pct((end_val / amt - 1) * 100))
    k[3].metric("Max drawdown", f"{dd_sel*100:.1f}%")
    pc = np.percentile(paths, [10, 50, 90], axis=0) * amt
    xs = np.arange(1, h + 1)
    fig = go.Figure()
    fig.add_scatter(x=xs, y=pc[2], name="90th pct", line=dict(color="#39ff9a", width=1))
    fig.add_scatter(x=xs, y=pc[0], name="10th pct", line=dict(color="#d62728", width=1), fill="tonexty", fillcolor="rgba(0,229,255,.07)")
    fig.add_scatter(x=xs, y=pc[1], name="Median", line=dict(color="#67f7ff", width=2))
    fig.update_layout(height=400, title=f"{sc_s}: simulated value of ₹{amt:,.0f} over {yrs} year(s)", xaxis_title="Trading days", yaxis_title="Rs", hovermode="x unified", legend=dict(orientation="h", y=1.1))
    st.plotly_chart(futuristic_fig(fig), width="stretch")
    st.caption(note + " These are scenario simulations of past behaviour, not predictions.")

# ================================================================= ANOMALIES
with tab_anom:
    c1, c2, c3 = st.columns([1, 1.5, 1.5])
    an_s = c1.selectbox("Stock", STOCKS, key="an_stock")
    meth = c2.radio("Method", ["Z-score", "IQR", "Rolling volatility"], horizontal=True, key="an_meth")
    thr = c3.slider("Threshold (σ or IQR multiple)", 2.0, 6.0, 3.0, 0.5, key="an_thr")
    pa = df_wide(basis)[an_s].dropna()
    ra = pa.pct_change().dropna() * 100
    if meth == "Z-score":
        z = (ra - ra.mean()) / ra.std()
        flag, why = z.abs() > thr, z.map(lambda v: f"{v:+.1f}σ from the mean daily return")
    elif meth == "IQR":
        q1, q3 = ra.quantile(.25), ra.quantile(.75)
        lo_f, hi_f = q1 - thr * (q3 - q1), q3 + thr * (q3 - q1)
        flag, why = (ra < lo_f) | (ra > hi_f), ra.map(lambda v: f"outside the {thr:.1f}×IQR fence [{lo_f:.2f}%, {hi_f:.2f}%]")
    else:
        zz = ra / ra.rolling(20).std().shift(1)
        flag, why = zz.abs() > thr, zz.map(lambda v: f"{v:+.1f}× the prior 20-day volatility")
    hits = ra[flag.fillna(False)]
    a1, a2 = st.columns(2)
    a1.metric("Flagged days", len(hits))
    a2.metric("Share of days", f"{len(hits) / len(ra) * 100:.1f}%")
    fig = go.Figure()
    fig.add_scatter(x=pa.index, y=pa, name="Close", line=dict(color="#9aa0a6", width=1.2))
    fig.add_scatter(x=hits.index, y=pa.loc[hits.index], mode="markers", name="Anomaly",
                    marker=dict(size=11, color="#d62728", line=dict(width=1, color="white")))
    fig.update_layout(height=430, title=f"{an_s}: price anomalies ({meth})", yaxis_title="Rs", hovermode="x unified", legend=dict(orientation="h", y=1.1))
    st.plotly_chart(futuristic_fig(fig), width="stretch")
    if len(hits):
        st.dataframe(pd.DataFrame({"Date": hits.index.date, "Return %": hits.round(2).values, "Why flagged": why.loc[hits.index].values}),
                     hide_index=True, width="stretch")
    st.caption("Runs on the price basis chosen in the sidebar: switch to **Raw** and the TCS / Infosys bonus issues appear as ~-50% shocks.")

