# ================================================================= SQL ANALYSIS
with tab_sqla:
    import re as _re

    _TECH = [
        ("CTE", r"\bWITH\b"), ("Window function", r"\bOVER\s*\("), ("LAG / LEAD", r"\b(LAG|LEAD)\s*\("),
        ("Ranking", r"\b(RANK|DENSE_RANK|ROW_NUMBER|NTILE)\s*\("), ("JOIN", r"\bJOIN\b"),
        ("Aggregation", r"\b(SUM|AVG|COUNT|MIN|MAX)\s*\("), ("CASE", r"\bCASE\b"),
        ("GROUP BY", r"\bGROUP\s+BY\b"), ("UNION", r"\bUNION\b"), ("Subquery", r"\(\s*SELECT\b"),
        ("CREATE TABLE/VIEW", r"\bCREATE\s+(TABLE|VIEW)\b"),
    ]

    def _techniques(sql):
        return [n for n, pat in _TECH if _re.search(pat, sql, _re.I)]

    st.subheader("SQL analysis")
    st.markdown(
        "Every number in this dashboard traces back to a SQL task. Browse each task below: the business question, "
        "the exact query, the technique it uses and its live result. Use **SQL playground** to edit and re-run any of them.")

    _rows = [{"Task": k, "Question": v["title"], "Techniques": ", ".join(_techniques(v["sql"])) or "Basic SELECT",
              "Lines of SQL": v["sql"].strip().count("\n") + 1} for k, v in SECTIONS.items()]
    _idx = pd.DataFrame(_rows)

    k1, k2, k3, k4 = st.columns(4)
    k1.metric("SQL tasks", len(_idx))
    k2.metric("Use window functions", int(_idx.Techniques.str.contains("Window").sum()))
    k3.metric("Use CTEs", int(_idx.Techniques.str.contains("CTE").sum()))
    k4.metric("Total lines of SQL", int(_idx["Lines of SQL"].sum()))

    with st.expander("Task index and techniques used", expanded=False):
        st.dataframe(_idx, width="stretch", hide_index=True)

    st.markdown("#### Explore a task")
    _ids = list(SECTIONS)
    _sel = st.selectbox("Choose task", _ids, format_func=lambda k: f"Task {k}: {SECTIONS[k]['title']}", key="sqla_pick")
    _sec = SECTIONS[_sel]
    _tech = _techniques(_sec["sql"])

    st.markdown(f"**Task {_sel}: {_sec['title']}**")
    if _tech:
        st.markdown(" ".join(f"`{t}`" for t in _tech))

    c_sql, c_res = st.columns([1, 1.2])
    with c_sql:
        st.markdown("**Query**")
        st.code(_sec["sql"].strip(), language="sql")
        st.download_button("Download .sql", _sec["sql"].strip().encode(), f"task_{_sel}.sql", "text/plain", key=f"sqla_dl_{_sel}")
    with c_res:
        st.markdown("**Result**")
        try:
            _res = df_task(_sel)
            st.caption(f"{len(_res):,} rows x {len(_res.columns)} columns")
            st.dataframe(_res, width="stretch", hide_index=True, height=340)
            st.download_button("Download result CSV", _res.to_csv(index=False).encode(), f"task_{_sel}_result.csv", "text/csv", key=f"sqla_csv_{_sel}")
        except Exception as e:
            _res = None
            st.error(f"Could not run this task: {e}")

    if _res is not None and len(_res) > 1:
        _num = _res.select_dtypes("number").columns.tolist()
        _cat = [c for c in _res.columns if c not in _num]
        if _num:
            with st.expander("Chart this result", expanded=True):
                _x = st.selectbox("X axis", list(_res.columns), index=list(_res.columns).index(_cat[0]) if _cat else 0, key="sqla_x")
                _y = st.selectbox("Y axis", [c for c in _num if c != _x] or _num, key="sqla_y")
                _kind = st.radio("Type", ["bar", "line"], horizontal=True, key="sqla_k")
                _plot = _res.head(500)
                _fn = px.bar if _kind == "bar" else px.line
                if "stock" in _plot.columns and _x != "stock":
                    _fig = _fn(_plot, x=_x, y=_y, color="stock", color_discrete_map=COLORS)
                else:
                    _fig = _fn(_plot, x=_x, y=_y)
                _fig.update_layout(height=380)
                st.plotly_chart(futuristic_fig(_fig), width="stretch")

    st.markdown("#### SQL concepts used in this project")
    _cc = st.columns(3)
    _notes = [
        ("CTEs", "Break long logic into named steps, e.g. cleaning prices, then computing signals, then ranking."),
        ("Window functions", "Moving averages and row-to-row comparisons (such as the 20/50-day signals) computed over each stock's price history without collapsing rows."),
        ("Data cleaning", "Bonus-issue adjustment: divide earlier prices by 2 so TCS and Infosys returns are not distorted."),
        ("Signals", "Golden-cross rule: 20-day average crossing above the 50-day gives Buy, below gives Sell."),
        ("Worst-day detection", "Ranking one-day moves surfaces the two fake ~50% 'crashes' caused by bonus issues."),
        ("Reproducibility", "Each dashboard metric can be re-derived in the playground, which keeps results auditable."),
    ]
    for i, (h, b) in enumerate(_notes):
        with _cc[i % 3]:
            st.markdown(f'<div class="insight-card"><div class="insight-kicker">{h}</div>'
                        f'<div class="insight-sub">{b}</div></div>', unsafe_allow_html=True)


